import datetime
import unittest

from daterange import parse_range

D = datetime.date


class TestClosedRanges(unittest.TestCase):
    def test_two_dates(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-31"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_same_day_is_allowed(self):
        self.assertEqual(parse_range("2026-10-01..2026-10-01"), (D(2026, 10, 1), D(2026, 10, 1)))

    def test_returns_date_objects(self):
        start, end = parse_range("2026-10-01..2026-10-31")
        self.assertIs(type(start), datetime.date)
        self.assertIs(type(end), datetime.date)


class TestPeriodTokens(unittest.TestCase):
    def test_month(self):
        self.assertEqual(parse_range("2026-02"), (D(2026, 2, 1), D(2026, 2, 28)))

    def test_month_leap_february(self):
        self.assertEqual(parse_range("2024-02"), (D(2024, 2, 1), D(2024, 2, 29)))

    def test_month_december_rolls_into_next_year(self):
        self.assertEqual(parse_range("2026-12"), (D(2026, 12, 1), D(2026, 12, 31)))

    def test_iso_week(self):
        self.assertEqual(parse_range("2026-W44"), (D(2026, 10, 26), D(2026, 11, 1)))

    def test_iso_week_crosses_year_boundary(self):
        self.assertEqual(parse_range("2020-W53"), (D(2020, 12, 28), D(2021, 1, 3)))

    def test_year(self):
        self.assertEqual(parse_range("2026"), (D(2026, 1, 1), D(2026, 12, 31)))

    def test_year_leap(self):
        self.assertEqual(parse_range("2024"), (D(2024, 1, 1), D(2024, 12, 31)))


class TestOpenEnds(unittest.TestCase):
    def test_open_start(self):
        self.assertEqual(parse_range("..2026-10-31"), (None, D(2026, 10, 31)))

    def test_open_end(self):
        self.assertEqual(parse_range("2026-10-01.."), (D(2026, 10, 1), None))

    def test_open_start_with_month(self):
        self.assertEqual(parse_range("..2026-02"), (None, D(2026, 2, 28)))

    def test_open_end_with_week(self):
        self.assertEqual(parse_range("2026-W44.."), (D(2026, 10, 26), None))

    def test_open_end_with_year(self):
        self.assertEqual(parse_range("..2026"), (None, D(2026, 12, 31)))


class TestWhitespace(unittest.TestCase):
    def test_spaces_around_whole_text(self):
        self.assertEqual(
            parse_range("  2026-10-01..2026-10-31  "),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_spaces_around_separator(self):
        self.assertEqual(
            parse_range("2026-10-01  ..  2026-10-31"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_tabs_and_newlines(self):
        self.assertEqual(
            parse_range("\t2026-10-01\t..\t2026-10-31\n"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_spaces_around_open_ends(self):
        self.assertEqual(parse_range(" .. 2026-10-31 "), (None, D(2026, 10, 31)))
        self.assertEqual(parse_range(" 2026-10-01 .. "), (D(2026, 10, 1), None))


class TestErrors(unittest.TestCase):
    def assertInvalid(self, text):
        with self.assertRaises(ValueError):
            parse_range(text)

    def test_empty_inputs(self):
        for text in ["", "   ", "\t\n"]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_lone_separator(self):
        for text in ["..", " .. ", "..."]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_end_before_start(self):
        self.assertInvalid("2026-10-31..2026-10-01")
        self.assertInvalid("2027-01-01..2026-12-31")

    def test_period_end_before_start(self):
        self.assertInvalid("2026-03..2026-02")
        self.assertInvalid("2026..2025")

    def test_bad_months(self):
        for text in ["2026-13", "2026-00", "2026-13-01", "2026-00-01"]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_bad_days(self):
        for text in ["2026-02-30", "2025-02-29", "2026-04-31", "2026-01-00", "2026-01-32"]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_bad_weeks(self):
        for text in ["2026-W54", "2026-W00", "2026-W60"]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_malformed_tokens(self):
        for text in [
            "2026-1-1",
            "2026-1",
            "26-10-01",
            "2026/10/01",
            "2026-W4",
            "2026W44",
            "garbage",
            "2026-10-01..garbage",
            "garbage..2026-10-01",
        ]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_too_many_separators(self):
        for text in [
            "2026-10-01..2026-10-02..2026-10-03",
            "2026-10-01...2026-10-02",
            "..2026-10-01..",
        ]:
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_internal_whitespace_in_token(self):
        for text in ["2026 10 01", "20 26", "2026-10-01..2026 -10-02"]:
            with self.subTest(text=text):
                self.assertInvalid(text)


if __name__ == "__main__":
    unittest.main()

